import{_ as t}from"./chunks/00-sidebar-overview.CFI0fTnD.js";import{_ as a}from"./chunks/12-audit.CWIaVMMc.js";import{_ as s,o as i,c as r,a2 as o}from"./chunks/framework.DUZafPzB.js";const g=JSON.parse('{"title":"Security & sensitive files","description":"","frontmatter":{},"headers":[],"relativePath":"features/security.md","filePath":"features/security.md","lastUpdated":1791394961000}'),n={name:"features/security.md"};function l(d,e,c,h,p,u){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="security-sensitive-files" tabindex="-1">Security &amp; sensitive files <a class="header-anchor" href="#security-sensitive-files" aria-label="Permalink to &quot;Security &amp; sensitive files&quot;">​</a></h1><p>filebox’s default posture: <strong>read-only browse, path jail, sensitive files denied</strong>. Two write capabilities (Transfer, Terminal) are explicit exceptions and need capability / local configuration.</p><p><img src="'+t+`" alt="Sidebar capability entries"></p><h2 id="read-only-protocol" tabindex="-1">Read-only protocol <a class="header-anchor" href="#read-only-protocol" aria-label="Permalink to &quot;Read-only protocol&quot;">​</a></h2><p>Browse paths have no write / delete / rename / arbitrary exec messages.</p><table tabindex="0"><thead><tr><th>Exception</th><th>Scope</th><th>Protections</th></tr></thead><tbody><tr><td><strong>Transfer</strong></td><td>Agent scratch directory only</td><td>Quotas, no overwrite, not a normal root</td></tr><tr><td><strong>Terminal</strong></td><td>Agent host shell (<strong>not sandboxed</strong>)</td><td>Agent-local TOTP; secret never enters the Hub</td></tr></tbody></table><h2 id="sensitive-files-denied-by-default-excerpt" tabindex="-1">Sensitive files denied by default (excerpt) <a class="header-anchor" href="#sensitive-files-denied-by-default-excerpt" aria-label="Permalink to &quot;Sensitive files denied by default (excerpt)&quot;">​</a></h2><p>Even inside authorized roots, matching paths are unreadable:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.git/  .ssh/  .gnupg/  .aws/  .kube/</span></span>
<span class="line"><span>.env*  *.pem  *.key  id_*  credentials*.json  *.sqlite*</span></span></code></pre></div><p>plus common credential locations such as shell history. Exact rules follow the current release implementation.</p><h2 id="path-jail" tabindex="-1">Path jail <a class="header-anchor" href="#path-jail" aria-label="Permalink to &quot;Path jail&quot;">​</a></h2><p>Browse is strictly limited to added roots; <code>..</code> and symlink escapes are blocked.</p><h2 id="auth-and-trust" tabindex="-1">Auth and trust <a class="header-anchor" href="#auth-and-trust" aria-label="Permalink to &quot;Auth and trust&quot;">​</a></h2><ul><li>User login happens on the Hub (PoW + session cookie + CSRF).</li><li>Each machine uses its own Agent token (Hub stores only a hash).</li><li>Agents dial out to the Hub; targets need no inbound exposure.</li><li>Production must use HTTPS to protect tokens and sessions.</li><li>Login events appear under sidebar <strong>Audit</strong>.</li></ul><p><img src="`+a+'" alt="Login audit"></p><h2 id="architecture-notes" tabindex="-1">Architecture notes <a class="header-anchor" href="#architecture-notes" aria-label="Permalink to &quot;Architecture notes&quot;">​</a></h2><p>Deeper Hub↔Agent trust boundaries, tokens, and rate limits live in the repo developer doc <a href="https://github.com/ZhimingYe/filebox/blob/main/docs/hub-agent-security-model.md" target="_blank" rel="noreferrer"><code>docs/hub-agent-security-model.md</code></a> (Chinese).</p>',17)])])}const y=s(n,[["render",l]]);export{g as __pageData,y as default};
